Ra = R1 + R2;
Rb = (R3*R4)/(R3+R4);
Req = (Ra*Rb)/(Ra+Rb);

f = 1/(2*pi*Req*C);

Rba = Rb/(Ra+Rb);
Rab = Ra/(Ra+Rb);

Sab = (pi/2)*f*(Rab)^2*4*k*T;
Sba = (pi/2)*f*(Rba)^2*4*k*T;

S1 = Sba*R1;
S2 = Sba*R2;
S3 = Sab*(Rb^2/R3);
S4 = Sab*(Rb^2/R4);

Stot = S1 + S2 + S3 + S4;

set_time_axis R1
plot S1
plot S2
plot S3
plot S4
plot Stot
